/* Compare teacher-forced traces generated by agreement.c. Standard C11 only.
 * Usage: compare_next_tokens reference.csv candidate.csv [candidate.csv ...]
 * Writes CSV to stdout. Returns 0 for a valid comparison, 1 for invalid input.
 * A prediction mismatch is a result, not a program error.
 */
#include <errno.h>
#include <limits.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    FILE *file;
    const char *path;
    unsigned long long vocab, context, tokens, count, previous_target;
} Trace;

static int fail(const Trace *t, const char *message) {
    fprintf(stderr, "%s: %s\n", t->path, message);
    return 0;
}

static int line(Trace *t, char *buffer, size_t size) {
    if (!fgets(buffer, (int)size, t->file))
        return ferror(t->file) ? -1 : 0;
    size_t n = strlen(buffer);
    if (!n || (buffer[n-1] != '\n' && !feof(t->file))) return -1;
    while (n && (buffer[n-1] == '\n' || buffer[n-1] == '\r')) buffer[--n] = '\0';
    return 1;
}

static int number(const char **cursor, unsigned long long *value) {
    const char *p = *cursor;
    char *end;
    if (*p < '0' || *p > '9') return 0;
    errno = 0;
    *value = strtoull(p, &end, 10);
    if (errno == ERANGE) return 0;
    *cursor = end;
    return 1;
}

static int metadata(Trace *t, const char *prefix, unsigned long long *value) {
    char buffer[512];
    size_t n = strlen(prefix);
    if (line(t, buffer, sizeof buffer) != 1 || strncmp(buffer, prefix, n))
        return fail(t, "missing/invalid trace metadata");
    const char *p = buffer + n;
    if (!number(&p, value) || *p) return fail(t, "invalid metadata number");
    return 1;
}

static int open_trace(Trace *t, const char *path) {
    char buffer[512];
    unsigned long long version;
    memset(t, 0, sizeof *t);
    t->path = path;
    t->file = fopen(path, "rb");
    if (!t->file) return fail(t, "cannot open trace");
    if (!metadata(t, "# agreement_format=", &version) || version != 1 ||
        !metadata(t, "# vocab_size=", &t->vocab) ||
        !metadata(t, "# seq_len=", &t->context) ||
        !metadata(t, "# token_count=", &t->tokens)) return fail(t, "unsupported trace header");
    if (!t->vocab || t->vocab > INT_MAX || t->context < 2 ||
        t->context > INT_MAX || t->tokens < 2 || t->tokens > INT_MAX)
        return fail(t, "metadata out of range");
    if (line(t, buffer, sizeof buffer) != 1 ||
        strcmp(buffer, "index,chunk_start,pos,input_token,target_token,predicted_token"))
        return fail(t, "invalid CSV column header");
    return 1;
}

/* Return 1 for a validated row, 0 for a complete trace, -1 for an error. */
static int row(Trace *t, unsigned long long values[6]) {
    char buffer[512];
    int state = line(t, buffer, sizeof buffer);
    if (state < 0) { fail(t, "read error or oversized row"); return -1; }
    if (!state) {
        if (t->count != t->tokens - 1) { fail(t, "incomplete trace"); return -1; }
        return 0;
    }
    const char *p = buffer;
    for (int i = 0; i < 6; ++i) {
        if (!number(&p, &values[i]) || (i < 5 ? *p != ',' : *p != '\0')) {
            fail(t, "malformed CSV row"); return -1;
        }
        if (i < 5) ++p;
    }
    unsigned long long start = (t->count / (t->context - 1)) * (t->context - 1);
    if (t->count >= t->tokens - 1 || values[0] != t->count ||
        values[1] != start || values[2] != t->count - start ||
        values[3] >= t->vocab || values[4] >= t->vocab || values[5] >= t->vocab ||
        (t->count && values[3] != t->previous_target)) {
        fail(t, "invalid token IDs, context positions, or input sequence"); return -1;
    }
    t->previous_target = values[4];
    ++t->count;
    return 1;
}

static void csv_string(const char *s) {
    putchar('"');
    for (; *s; ++s) { if (*s == '"') putchar('"'); putchar(*s); }
    putchar('"');
}

static int compare(const char *reference, const char *candidate) {
    Trace a = {0}, b = {0};
    unsigned long long matches = 0, total = 0, x[6], y[6];
    int ok = 0;
    if (!open_trace(&a, reference) || !open_trace(&b, candidate)) goto cleanup;
    if (a.vocab != b.vocab || a.context != b.context || a.tokens != b.tokens) {
        fail(&b, "metadata differs from FP32 reference"); goto cleanup;
    }
    for (;;) {
        int ar = row(&a, x), br = row(&b, y);
        if (ar < 0 || br < 0) goto cleanup;
        if (ar != br) { fail(&b, "trace length differs from reference"); goto cleanup; }
        if (!ar) break;
        for (int i = 0; i < 5; ++i) {
            if (x[i] != y[i]) { fail(&b, "input tokens or contexts differ from reference"); goto cleanup; }
        }
        matches += x[5] == y[5];
        ++total;
    }
    csv_string(candidate);
    printf(",%llu,%llu,%llu,%.6f\n", total, matches, total-matches,
           100.0 * (double)matches / (double)total);
    ok = 1;
cleanup:
    if (a.file) fclose(a.file);
    if (b.file) fclose(b.file);
    return ok;
}

int main(int argc, char **argv) {
    if (argc < 3) {
        fprintf(stderr, "Usage: %s reference.csv candidate.csv [candidate.csv ...]\n", argv[0]);
        return EXIT_FAILURE;
    }
    puts("variant,positions,matches,mismatches,agreement_percent");
    for (int i = 2; i < argc; ++i)
        if (!compare(argv[1], argv[i])) return EXIT_FAILURE;
    if (fflush(stdout) || ferror(stdout)) {
        fprintf(stderr, "Cannot write comparison results\n");
        return EXIT_FAILURE;
    }
    return EXIT_SUCCESS;
}
